import * as T from './vendor/three.module.js';
import {ITEMS} from './inventory.js';
function painted(id){if(typeof document==='undefined'||!document.createElement)return null;const c=document.createElement('canvas');if(!c.getContext)return null;c.width=c.height=64;const x=c.getContext('2d');x.fillStyle=id==='gold'?'#b99a43':id==='bone'?'#bdbca2':'#867755';x.fillRect(0,0,64,64);let seed=41;for(let i=0;i<280;i++){seed=(seed*1664525+1013904223)>>>0;x.fillStyle=i%2?'#ffffff18':'#141a2328';x.fillRect(seed%64,(seed>>>8)%64,1,2)}if(id==='memory_medallion'){x.strokeStyle='#e0cf8a';x.lineWidth=3;x.beginPath();x.arc(32,32,25,0,Math.PI*2);x.stroke();x.beginPath();x.moveTo(20,43);x.lineTo(24,22);x.quadraticCurveTo(32,12,40,22);x.lineTo(44,43);x.closePath();x.stroke();x.beginPath();x.arc(32,47,3,0,Math.PI*2);x.stroke()}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.magFilter=T.NearestFilter;return t}
export function lootModel(parent,id,count=1){const g=new T.Group();g.userData.itemId=id;parent.add(g);const material=new T.MeshStandardMaterial({color:id==='gold'?0xf6cf61:id==='bone'?0xece7cc:0xc2b074,map:['gold','bone','memory_medallion'].includes(id)?painted(id):null,roughness:.7,metalness:id==='gold'?.5:0,emissive:id==='gold'?0x624809:id==='bone'?0x35412f:0x395c50,emissiveIntensity:.7});function add(geo,mat,x=0,y=0,z=0){const m=new T.Mesh(geo,mat);m.position.set(x,y,z);g.add(m);return m}
 if(id==='gold'){for(let i=0;i<Math.min(3,count);i++)add(new T.CylinderGeometry(.16,.16,.045,14),material,0,i*.05,0)}else if(id==='bone'){const shaft=add(new T.CylinderGeometry(.045,.045,.48,7),material);shaft.rotation.z=-.9;for(const s of [-1,1])for(const side of [-1,1])add(new T.SphereGeometry(.07,7,5),material,s*.18+side*.035,s*.17-side*.035,0)}else if(id==='ectoplasm'){material.color.setHex(0xa7ffeb);material.map=null;material.emissive.setHex(0x57c4a8);material.transparent=true;material.opacity=.8;add(new T.IcosahedronGeometry(.23,1),material,0,.08,0);for(let i=0;i<3;i++)add(new T.SphereGeometry(.06,8,6),material,Math.sin(i*2)*.17,-.1+i*.08,Math.cos(i*2)*.13)}else{const medallion=add(new T.CylinderGeometry(.23,.23,.055,24),material);medallion.rotation.x=Math.PI/2;const loop=add(new T.TorusGeometry(.06,.018,5,12),material,0,.27,0)}
 const ring=add(new T.TorusGeometry(.32,.012,5,24),new T.MeshBasicMaterial({color:id==='gold'?0xffd877:id==='bone'?0xdce8ba:0xa2f3de,transparent:true,opacity:.55}),0,-.12,0);ring.rotation.x=Math.PI/2;
 if(typeof document!=='undefined'&&document.createElement){const c=document.createElement('canvas');if(c.getContext){c.width=320;c.height=56;const x=c.getContext('2d');x.font='bold 25px Arial';x.textAlign='center';x.lineWidth=5;x.strokeStyle='#0c1520';const label=(id==='gold'?'Золото':ITEMS[id]?.name||id)+(count>1?' ×'+count:'');x.strokeText(label,160,37);x.fillStyle=id==='gold'?'#ffe299':'#e0f3db';x.fillText(label,160,37);const map=new T.CanvasTexture(c),sprite=new T.Sprite(new T.SpriteMaterial({map,transparent:true,depthWrite:false}));sprite.position.y=.65;sprite.scale.set(1.8,.32,1);g.add(sprite)}}return g}
export function disposeLoot(g){g.removeFromParent();const geos=new Set(),mats=new Set(),maps=new Set();g.traverse(o=>{if(o.geometry)geos.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[]){mats.add(m);if(m.map)maps.add(m.map)}});for(const v of [...geos,...mats,...maps])v.dispose()}
